-- ============================================================================
-- Ascendant tome + shard drops -- global-loot wiring (restore + scale to 85)
-- Date: 2026-10-03
--
-- The cross-class AA tome system (Illegible Tomes 121571-121618 turned in at
-- Bazaar class trainers for tier credits, plugins/ascendant_insight_trainer.pl)
-- has no drop wiring on EQS: the 27 Magelo-GEN loottables/lootdrops (96997-97014)
-- that look like carriers never contained tome entries in any snapshot, and most
-- are orphaned from NPCs. The ad-hoc live-DB wiring that once functioned left no
-- artifact. This restores drops the way Ascendant-Server does it (their
-- global_npc.pl script rates), as DB loot wiring, scaled to the level-85 cap.
--
-- Ascendant rates (one-in-N per mob kill, random class tome of the tier):
--   mob lvl 1-10: Greater 1/165, Exalted 1/175, Ascendant 1/185
--           11-20: 1/155, 1/165, 1/175
--           21-30: 1/150, 1/155, 1/160
--           31-40: 1/150, 1/145, 1/140
--           41+  : 1/145, 1/140, 1/135   (continued for 41-55/56-70/71-85)
-- Per entry in a 16-class tier pool, chance = 100/(16*N) percent, so the
-- tier's aggregate per-kill rate is ~1/N. loottable_entries.droplimit = 1
-- caps a kill at one tome (Ascendant could rarely multi-drop).
--
-- Ancient Shard of Ascendant Power (121856, Khael the Spellforger's upgrade
-- catalyst): rare drop off RAID TARGETS ONLY (global_loot raid = 1 matches
-- npc_types.raid_target, see zone/global_loot_manager.cpp PassesRules) at 10%
-- per kill. The server's live raid content runs through Underfoot, which is
-- the intended "up to UF" scope; global_loot has no expansion rule in this
-- fork (Expansion:CurrentExpansion = -1), and loot expansion columns compare
-- against the server-wide setting, so the cap is inherent to spawned content.
-- NOTE: unlike Ascendant's script, raid targets are NOT excluded from tomes
-- (global_loot rare/raid = 0 creates no rule in this fork); they just also
-- carry the shard.
--
-- Idempotent: deletes the ids it owns before inserting.
-- Twin of ManifestEntry .version = 99 in
-- common/database/database_update_manifest_custom.cpp
-- ============================================================================

DELETE FROM `global_loot` WHERE `id` BETWEEN 178710 AND 178717;
DELETE FROM `loottable_entries` WHERE `loottable_id` BETWEEN 178710 AND 178717;
DELETE FROM `lootdrop_entries` WHERE `lootdrop_id` BETWEEN 178710 AND 178717;
DELETE FROM `lootdrop` WHERE `id` BETWEEN 178710 AND 178717;
DELETE FROM `loottable` WHERE `id` BETWEEN 178710 AND 178717;






